70	let mplJsLoading: Promise<void> | null = null;
71	
72	async function ensureMplJs(jsUrl: string): Promise<void> {
73	  if (window.mpl) {
74	    return;
75	  }
76	  if (mplJsLoading) {
77	    return mplJsLoading;
78	  }
79	  mplJsLoading = new Promise<void>((resolve, reject) => {
80	    const script = document.createElement("script");
81	    script.src = jsUrl;
82	    script.onload = () => resolve();
83	    script.onerror = () => {
84	      mplJsLoading = null;
85	      reject(new Error("Failed to load mpl.js"));
86	    };
87	    document.head.append(script);
88	  });
89	  return mplJsLoading;
90	}
