92	/**
93	 * Patch mpl.js toolbar image references to use inline data URIs.
94	 *
95	 * mpl.js sets `icon_img.src = '_images/' + image + '.png'` and
96	 * `icon_img.srcset = '_images/' + image + '_large.png 2x'`.
97	 *
98	 * We observe the container for new <img> elements and rewrite their
99	 * src/srcset to the inlined base64 data URIs.
100	 */
101	function patchToolbarImages(
102	  container: HTMLElement,
103	  toolbarImages: Record<string, string>,
104	): () => void {
105	  const patchImg = (img: HTMLImageElement) => {
106	    const src = img.getAttribute("src") || "";
107	    const match = src.match(/_images\/(.+)\.png$/);
108	    if (match) {
109	      const name = match[1];
110	      const dataUri = toolbarImages[name];
111	      if (dataUri) {
112	        img.src = dataUri;
113	      }
114	    }
115	    const srcset = img.getAttribute("srcset") || "";
116	    const srcsetMatch = srcset.match(/_images\/(.+)\.png\s+2x$/);
117	    if (srcsetMatch) {
118	      const name = srcsetMatch[1];
119	      const dataUri = toolbarImages[name];
120	      if (dataUri) {
121	        img.srcset = `${dataUri} 2x`;
122	      }
123	    }
124	  };
125	
126	  // Patch any existing images
127	  for (const img of container.querySelectorAll("img")) {
128	    patchImg(img);
129	  }
130	
131	  // Observe for new images added by mpl.js
132	  const observer = new MutationObserver((mutations) => {
133	    for (const mutation of mutations) {
134	      for (const node of mutation.addedNodes) {
135	        if (node instanceof HTMLImageElement) {
136	          patchImg(node);
137	        } else if (node instanceof HTMLElement) {
138	          for (const img of node.querySelectorAll("img")) {
139	            patchImg(img);
140	          }
141	        }
142	      }
143	    }
144	  });
145	
146	  observer.observe(container, { childList: true, subtree: true });
147	  return () => observer.disconnect();
148	}
