150	function injectCss(container: HTMLElement, cssUrl: string): () => void {
151	  const link = document.createElement("link");
152	  link.rel = "stylesheet";
153	  link.href = cssUrl;
154	  container.append(link);
155	  return () => link.remove();
156	}
