158	const MplInteractiveSlot = (props: IPluginProps<ModelIdRef, Data>) => {
159	  const { mplJsUrl, cssUrl, toolbarImages, width, height } = props.data;
160	  const { model_id: modelId } = props.value;
161	  const containerRef = useRef<HTMLDivElement>(null);
162	  const figureRef = useRef<MplFigure | null>(null);
163	  const wsRef = useRef<MplCommWebSocket | null>(null);
164	
165	  const setupFigure = useCallback(
166	    async (container: HTMLElement) => {
167	      // Load mpl.js globally (only once, via <script src>)
168	      await ensureMplJs(mplJsUrl);
169	
170	      if (!window.mpl) {
171	        Logger.error("mpl.js failed to load");
172	        return;
173	      }
174	
175	      // Get the model from MODEL_MANAGER
176	      let model: Model<ModelState>;
177	      try {
178	        model = await MODEL_MANAGER.get(modelId);
179	      } catch {
180	        Logger.error("Failed to get model for mpl interactive", modelId);
181	        return;
182	      }
183	
184	      // Create the fake WebSocket
185	      const fakeWs = new MplCommWebSocket((msg: unknown) => {
186	        // Send from frontend → backend via model custom message
187	        model.send(msg);
188	      });
189	      wsRef.current = fakeWs;
190	
191	      // Listen for backend → frontend messages via model custom events
192	      const handleCustomMessage = (
193	        content: { type: string; data?: unknown; format?: string },
194	        buffers?: readonly DataView[],
195	      ) => {
196	        if (!content) {
197	          return;
198	        }
199	
200	        if (content.type === "json") {
201	          fakeWs.receiveJson(content.data);
202	        } else if (content.type === "binary" && buffers && buffers.length > 0) {
203	          fakeWs.receiveBinary(buffers[0]);
204	        } else if (
205	          content.type === "download" &&
206	          buffers &&
207	          buffers.length > 0
208	        ) {
209	          const fmt = content.format || "png";
210	          const dv = buffers[0];
211	          const ab = dv.buffer.slice(
212	            dv.byteOffset,
213	            dv.byteOffset + dv.byteLength,
214	          ) as ArrayBuffer;
215	          downloadBlob(
216	            new Blob([ab], { type: `image/${fmt}` }),
217	            `figure.${fmt}`,
218	          );
219	        }
220	      };
221	
222	      model.on("msg:custom", handleCustomMessage as any);
223	
224	      // Create the mpl figure
225	      const figId = modelId;
226	      const ondownload = (_figure: MplFigure, format: string) => {
227	        // Send download request to backend
228	        model.send({ type: "download", format });
229	      };
230	
231	      const fig = new window.mpl.figure(figId, fakeWs, ondownload, container);
232	      figureRef.current = fig;
233	
234	      // Set the canvas_div to the backend's figure size so the
235	      // ResizeObserver doesn't trigger an immediate resize cycle.
236	      // mpl.js creates: fig.root > [titlebar, canvas_div, toolbar]
