120	  > | null>(null);
121	  const [loaded, setLoaded] = useState<boolean>(false);
122	  const [rendered, setRendered] = useState<string | null>(null);
123	
124	  // Store functions in a ref so the callback captured by EventBuffer stays current
125	  const functionsRef = useRef(functions);
126	  functionsRef.current = functions;
127	
128	  const processEvents = useCallback(() => {
129	    if (!eventBufferRef.current) {
130	      return;
131	    }
132	
133	    const events = eventBufferRef.current.getAndClear();
134	    if (events.length === 0) {
135	      return;
136	    }
137	
138	    // Use the event's own document — it is always current, even when
139	    // DynamicMap/HoloViews has replaced the document after embedding.
140	    const firstEvent = events.at(0);
141	    if (!isDocumentEvent(firstEvent)) {
142	      return;
143	    }
144	    const doc = firstEvent.document;
145	
146	    // Keep only events that belong to this document
147	    const sameDocEvents = events.filter(
148	      (ev) => isDocumentEvent(ev) && ev.document === doc,
149	    );
150	
151	    const patch = doc.create_json_patch(sameDocEvents);
152	    const message = window.Bokeh.protocol.Message.create(
153	      "PATCH-DOC",
154	      {},
155	      patch,
156	    );
157	    const buffers: ArrayBuffer[] = [];
158	    message.content = extractBuffers(message.content, buffers);
159	    functionsRef.current.send_to_widget({ message, buffers }).catch((error) => {
160	      Logger.warn("Failed to send Panel event to backend", error);
161	    });
162	  }, []);
163	
164	  const eventBufferRef = useRef<EventBuffer<unknown> | null>(
165	    new EventBuffer(processEvents),
166	  );
167	
168	  // Load the bokeh extension
169	  useEffect(() => {
170	    // Already loaded
171	    if (isBokehLoaded()) {
172	      setLoaded(true);
173	      return;
174	    }
175	
176	    // Load the extension
177	    if (extension) {
178	      const script = document.createElement("script");
179	      script.innerHTML = extension;
180	      document.head.append(script);
181	    }
182	
183	    // Check if Bokeh is loaded every 10ms
184	    const checkBokeh = setInterval(() => {
185	      if (isBokehLoaded()) {
186	        setLoaded(true);
187	        clearInterval(checkBokeh);
188	      }
189	    }, 10);
190	
191	    return () => clearInterval(checkBokeh);
192	  }, [extension, setLoaded]);
