201	      }
202	
203	      const message = MessageSchema.parse(e.detail.message);
204	      const buffers = e.detail.buffers;
205	      const receiver = receiverRef.current;
206	
207	      if (!receiver) {
208	        return;
209	      }
210	
211	      const content = message.content;
212	      if (content !== null && typeof message.content !== "string") {
