215	          processEvents();
216	        }
217	        return;
218	      }
219	
220	      const doc = getDoc(rootModelIdRef.current);
221	      if (!doc) {
222	        return;
223	      }
224	
225	      if (buffers && buffers.length > 0) {
226	        // Check if we already have an ArrayBuffer
227	        const buffer = buffers[0];
228	        if (buffer instanceof ArrayBuffer) {
