4	import type { AnyWidget, Experimental } from "@anywidget/types";
5	import { asRemoteURL } from "@/core/runtime/config";
6	import { resolveVirtualFileURL } from "@/core/static/files";
7	import { isStaticNotebook } from "@/core/static/static-state";
8	import { Logger } from "@/utils/Logger";
9	import type { Model } from "./model";
10	import type { ModelState, WidgetModelId } from "./types";
11	
12	export const experimental: Experimental = {
13	  invoke: async () => {
14	    const message =
15	      "anywidget.invoke not supported in marimo. Please file an issue at https://github.com/marimo-team/marimo/issues";
16	    Logger.warn(message);
17	    throw new Error(message);
18	  },
19	};
