21	export type RenderFn = (el: HTMLElement, signal: AbortSignal) => Promise<void>;
22	
23	/**
24	 * Polyfill for AbortSignal.any. Returns a signal that aborts when any of the
25	 * input signals abort. This can be removed once the Node.js test environment
26	 * (jsdom) supports AbortSignal.any natively.
27	 */
28	function abortSignalAny(signals: AbortSignal[]): AbortSignal {
29	  if (typeof AbortSignal.any === "function") {
30	    return AbortSignal.any(signals);
31	  }
32	  const controller = new AbortController();
33	  for (const signal of signals) {
34	    if (signal.aborted) {
35	      controller.abort(signal.reason);
36	      return controller.signal;
37	    }
38	    signal.addEventListener("abort", () => controller.abort(signal.reason), {
39	      once: true,
40	    });
41	  }
42	  return controller.signal;
43	}
