45	/**
46	 * Deduplicates ESM imports by jsHash.
47	 * A single import is shared across all widget instances using the same module.
48	 */
49	class WidgetDefRegistry {
50	  #cache = new Map<string, Promise<any>>();
51	
52	  /**
53	   * Get (or start) the ESM import for a widget module.
54	   * Cached by jsHash so multiple instances share one import.
55	   */
56	  getModule(jsUrl: string, jsHash: string): Promise<any> {
57	    const cached = this.#cache.get(jsHash);
58	    if (cached) {
59	      return cached;
60	    }
61	
62	    const promise = this.#doImport(jsUrl).catch((error) => {
63	      // On failure, remove from cache so a retry with a new URL can work
64	      this.#cache.delete(jsHash);
65	      throw error;
66	    });
67	
68	    this.#cache.set(jsHash, promise);
69	    return promise;
70	  }
71	
72	  /**
73	   * Invalidate a cached module (e.g. for hot-reload support).
74	   */
75	  invalidate(jsHash: string): void {
76	    Logger.debug(
77	      `[WidgetDefRegistry] Invalidating module cache for hash=${jsHash}`,
78	    );
79	    this.#cache.delete(jsHash);
80	  }
81	
82	  async #doImport(jsUrl: string): Promise<any> {
83	    let url = asRemoteURL(jsUrl).toString();
84	    if (isStaticNotebook()) {
85	      url = resolveVirtualFileURL(url);
86	    }
87	    return import(/* @vite-ignore */ url);
88	  }
89	}
90	
91	/**
92	 * Connects a Model to a resolved AnyWidget definition.
93	 * Owns the initialize lifecycle and produces a render function.
94	 *
95	 * Per AFM spec:
96	 * - initialize() is called once per model (or once per hot-reload)
97	 * - render() (the returned function) is called once per view
98	 */
99	class WidgetBinding<T extends ModelState = ModelState> {
100	  #controller: AbortController | undefined;
101	  #widgetDef: AnyWidget<T> | undefined;
102	  #render: RenderFn | undefined;
103	
104	  /**
105	   * Bind a widget definition to a model.
106	   * If the same def is already bound, returns the cached render function.
107	   * If a different def is provided (hot reload), tears down the old binding
108	   * and re-initializes.
109	   */
110	  async bind(widgetDef: AnyWidget<T>, model: Model<T>): Promise<RenderFn> {
111	    // Already initialized with the same widget - return cached render
112	    if (this.#render && this.#widgetDef === widgetDef) {
113	      return this.#render;
114	    }
115	
116	    // If widgetDef changed (hot reload), destroy old and re-initialize
117	    if (this.#render && this.#widgetDef !== widgetDef) {
118	      Logger.debug(
119	        "[WidgetBinding] Hot-reload detected, aborting previous binding",
120	      );
121	      this.#controller?.abort();
122	      this.#controller = undefined;
123	      this.#render = undefined;
124	    }
125	
126	    this.#widgetDef = widgetDef;
127	    this.#controller = new AbortController();
128	    const bindingSignal = this.#controller.signal;
129	
130	    // Resolve the widget definition (call if it's a function)
131	    const widget =
132	      typeof widgetDef === "function" ? await widgetDef() : widgetDef;
133	
134	    // Call initialize once per model
135	    const cleanup = await widget.initialize?.({ model, experimental });
136	    if (cleanup) {
137	      bindingSignal.addEventListener("abort", cleanup);
138	    }
139	
140	    // Store and return the render closure
141	    this.#render = async (el: HTMLElement, viewSignal: AbortSignal) => {
142	      const renderCleanup = await widget.render?.({
143	        model,
144	        el,
145	        experimental,
146	      });
147	      if (renderCleanup) {
148	        // Cleanup when either the view unmounts or the binding is destroyed
149	        const combined = abortSignalAny([viewSignal, bindingSignal]);
150	        combined.addEventListener("abort", () => {
151	          const reason = viewSignal.aborted
152	            ? "view unmount"
153	            : "binding destroyed";
154	          Logger.debug(
155	            `[WidgetBinding] Render cleanup triggered (reason: ${reason})`,
156	          );
157	          renderCleanup();
158	        });
159	      }
160	    };
161	
162	    return this.#render;
163	  }
164	
165	  /**
166	   * Destroy this binding, aborting the initialize lifecycle.
167	   */
168	  destroy(): void {
169	    Logger.debug(
170	      "[WidgetBinding] Destroying binding, aborting initialize lifecycle",
171	    );
172	    this.#controller?.abort();
173	    this.#controller = undefined;
174	    this.#widgetDef = undefined;
175	    this.#render = undefined;
176	  }
177	}
