179	/**
180	 * Maps WidgetModelId to WidgetBinding instances.
181	 * Singleton that manages the lifecycle of all bindings.
182	 */
183	class BindingManager {
184	  #bindings = new Map<WidgetModelId, WidgetBinding<any>>();
185	
186	  getOrCreate(modelId: WidgetModelId): WidgetBinding<any> {
187	    let binding = this.#bindings.get(modelId);
188	    if (!binding) {
189	      binding = new WidgetBinding();
190	      this.#bindings.set(modelId, binding);
191	    }
192	    return binding;
193	  }
194	
195	  destroy(modelId: WidgetModelId): void {
